import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { AppProvider, useApp } from './context/AppContext';
import Navbar from './Navbar';
import AuthPage from './AuthPage';
import HobbiesSelect from './HobbiesSelect';
import FeedPage from './FeedPage';
import PostDetailPage from './PostDetailPage';
import ChatroomPage from './ChatroomPage';

function ProtectedRoute({ children }) {
  const { user, authChecked } = useApp();

  if (!authChecked) {
    return <div style={{ padding: '40px', textAlign: 'center', color: '#666' }}>Verifying session…</div>;
  }

  if (!user) return <Navigate to="/auth" replace />;
  return children;
}

function AppRoutes() {
  return (
    <>
      <Navbar />
      <Routes>
        <Route path="/auth" element={<AuthPage />} />
        <Route path="/hobbies" element={<ProtectedRoute><HobbiesSelect /></ProtectedRoute>} />
        <Route path="/feed" element={<ProtectedRoute><FeedPage /></ProtectedRoute>} />
        <Route path="/post/:id" element={<ProtectedRoute><PostDetailPage /></ProtectedRoute>} />
        <Route path="/chatroom/:id" element={<ProtectedRoute><ChatroomPage /></ProtectedRoute>} />
        <Route path="*" element={<Navigate to="/auth" replace />} />
      </Routes>
    </>
  );
}

export default function App() {
  return (
    <AppProvider>
      <BrowserRouter future={{ v7_startTransition: true, v7_relativeSplatPath: true }}>
        <AppRoutes />
      </BrowserRouter>
    </AppProvider>
  );
}
